#include "revenge/dependency_graph.hpp"
#include <iostream>
#include <stdexcept>
using namespace revenge;
void check(bool ok){if(!ok)throw std::runtime_error("dependency graph assertion");}
int main(){try{Image root{},a{},b{},unused{};root.imports={{"A.DLL",{"x","y"},{}},{"a.dll",{"z"},{}},{"KERNEL32.dll",{"n"},{}}};a.imports={{"B.dll",{"a"},{}},{"kernel32.DLL",{"m","n"},{}},{"../bad.dll",{"q"},{}}};b.imports={{"A.dll",{"k"},{}},{"missing.dll",{"m"},{}}};unused.imports={{"other.dll",{"k"},{}}};std::vector<std::pair<std::string,Image>> supplied{{"a.dll",a},{"b.dll",b},{"unused.dll",unused}};auto s=dependency_graph_report("root.exe",root,supplied);check(s.find("Reachable supplied files: 3 / 4; module edges: 6; supplied edges: 3; symbol references: 9; distinct unprovided modules: 2; invalid descriptors: 1")!=std::string::npos);check(s.find("Unprovided: kernel32.dll | 3 symbol references")!=std::string::npos);check(s.find("Not reached by direct imports: unused.dll")!=std::string::npos);check(s.find("other.dll")==std::string::npos);supplied.emplace_back("A.DLL",a);bool rejected=false;try{dependency_graph_report("root.exe",root,supplied);}catch(const std::runtime_error&){rejected=true;}check(rejected);std::cout<<"Dependency graph: direct reachability, cycles, duplicate edges, case, missing modules and invalid names passed.\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
